 void DrawMarks(Graphics g,bool editing){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;foreach(var m in marks){var c=Color.FromArgb(m.Color);using(var pen=new Pen(c,m.Width)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;
 if(m.Kind=="Flèche"){using(var cap=new AdjustableArrowCap(4,5,true)){pen.CustomEndCap=cap;g.DrawLine(pen,m.X,m.Y,m.BX,m.BY);}}
 else if(m.Kind=="Loupe"){float r=m.Size/2;float vx=m.X-m.SX,vy=m.Y-m.SY;float length=(float)Math.Sqrt(vx*vx+vy*vy);if(m.Link&&length>r){g.DrawLine(pen,m.SX,m.SY,m.X-vx*r/length,m.Y-vy*r/length);}if(!m.InPlace)using(var shadow=new SolidBrush(Color.FromArgb(40,0,0,0)))g.FillEllipse(shadow,m.X-r+4,m.Y-r+6,m.Size,m.Size);var state=g.Save();using(var path=new GraphicsPath()){path.AddEllipse(m.X-r,m.Y-r,m.Size,m.Size);g.SetClip(path,CombineMode.Intersect);g.FillEllipse(Brushes.White,m.X-r,m.Y-r,m.Size,m.Size);g.DrawImage(photo,new RectangleF(m.X-r,m.Y-r,m.Size,m.Size),new RectangleF(m.SX-r/m.Zoom,m.SY-r/m.Zoom,m.Size/m.Zoom,m.Size/m.Zoom),GraphicsUnit.Pixel);}g.Restore(state);if(!m.InPlace)using(var white=new Pen(Color.White,m.Width+5))g.DrawEllipse(white,m.X-r,m.Y-r,m.Size,m.Size);g.DrawEllipse(pen,m.X-r,m.Y-r,m.Size,m.Size);
 if(editing&&!m.InPlace){float sr=r/m.Zoom;using(var target=new Pen(m==selected?c:Color.FromArgb(150,c),1.5f/scale)){target.DashStyle=DashStyle.Dash;g.DrawEllipse(target,m.SX-sr,m.SY-sr,sr*2,sr*2);g.DrawLine(target,m.SX-9/scale,m.SY,m.SX+9/scale,m.SY);g.DrawLine(target,m.SX,m.SY-9/scale,m.SX,m.SY+9/scale);}if(m==selected)using(var badge=new Font("Segoe UI",10/scale,FontStyle.Bold))g.DrawString("Loupe ×"+m.Zoom.ToString("0.0"),badge,Brushes.DimGray,m.X-r,m.Y+r+9/scale);}}
 else if(m.Kind=="Flou local"){DrawLocalBlur(g,m,editing);}
 else if(m.Kind=="Zone nette"){if(editing){using(var frame=new Pen(Color.FromArgb(m.Color),1/scale)){frame.DashStyle=DashStyle.Dash;g.DrawRectangle(frame,Rectangle.Round(MarkBounds(m)));}}}
 else if(m.Kind=="Surligneur"){using(var brush=new SolidBrush(Color.FromArgb(75,c)))g.FillRectangle(brush,MarkBounds(m));}
 else if(m.Kind=="Masquer"){using(var brush=new SolidBrush(c))g.FillRectangle(brush,Math.Min(m.X,m.BX),Math.Min(m.Y,m.BY),Math.Abs(m.BX-m.X),Math.Abs(m.BY-m.Y));}
 else {float f=m.Kind=="Numéro"?Math.Max(16,m.Size/5):Math.Max(14,m.Size/5);using(var font=new Font("Segoe UI",f,FontStyle.Bold)){if(m.Kind=="Numéro"){float d=f*1.8f;var badgeRect=new RectangleF(m.X-d/2,m.Y-d/2,d,d);using(var shadow=new SolidBrush(Color.FromArgb(55,0,0,0)))g.FillEllipse(shadow,badgeRect.X+2,badgeRect.Y+4,d,d);Color light=Color.FromArgb(Math.Min(255,c.R+35),Math.Min(255,c.G+35),Math.Min(255,c.B+35));using(var brush=new LinearGradientBrush(badgeRect,light,c,LinearGradientMode.Vertical))g.FillEllipse(brush,badgeRect);using(var rim=new Pen(Color.White,2))g.DrawEllipse(rim,badgeRect);var fmt=new StringFormat(){Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center};g.DrawString(m.Text,font,Brushes.White,new RectangleF(m.X-d/2,m.Y-d/2,d,d),fmt);}else {using(var path=new GraphicsPath()){path.AddString(m.Text,font.FontFamily,(int)FontStyle.Bold,f*96/72,new PointF(m.X,m.Y),StringFormat.GenericDefault);using(var outline=new Pen(Color.White,4)){g.DrawPath(outline,path);}using(var brush=new SolidBrush(c))g.FillPath(brush,path);}}}}
 }
 if(editing&&m==selected){if(m.Kind=="Flou local"){DrawBlurHandle(g,m.X,m.Y);DrawBlurHandle(g,m.BX,m.BY);continue;}DrawHandle(g,m.X,m.Y);if(m.Kind=="Flèche"||m.Kind=="Masquer"||m.Kind=="Surligneur"||m.Kind=="Zone nette"||m.Kind=="Flou local")DrawHandle(g,m.BX,m.BY);if(m.Kind=="Loupe"){if(!m.InPlace)DrawSourceHandle(g,m.SX,m.SY);DrawSizeHandle(g,m.X+m.Size/2,m.Y);}}}}
 void DrawHandle(Graphics g,float x,float y){float r=6/scale;g.FillEllipse(Brushes.White,x-r,y-r,r*2,r*2);using(var p=new Pen(Color.DodgerBlue,1.5f/scale))g.DrawEllipse(p,x-r,y-r,r*2,r*2);}
 void Down(object sender,MouseEventArgs e){if(photo==null||e.Button!=MouseButtons.Left||panning||spaceHeld)return;imageSelected=false;var p=ImagePoint(e.Location);if(!ViewRect.Contains(Point.Round(p)))return;if(CropDown(p))return;last=p;string mode=tool.Text;handle=0;
 // A lens remains directly editable from either its enlarged circle or its source target.
 if((mode=="Sélection"||mode=="Loupe")&&(ModifierKeys&Keys.Control)==0){Mark lens=null;bool source=false;for(int i=marks.Count-1;i>=0;i--)if(marks[i].Kind=="Loupe"&&HitMark(marks[i],p)){lens=marks[i];break;}if(lens==null)for(int i=marks.Count-1;i>=0;i--){var candidate=marks[i];if(candidate.Kind=="Loupe"&&!candidate.InPlace&&Dist(p,candidate.SX,candidate.SY)<=Math.Max(12/scale,candidate.Size/(2*Math.Max(1,candidate.Zoom)))){lens=candidate;source=true;break;}}if(lens!=null&&(mode=="Loupe"||source)){selected=lens;selection.Clear();selection.Add(lens);tool.SelectedIndex=0;mode="Sélection";if(source)handle=2;}}
 if(mode=="Sélection"){
 bool ctrl=(ModifierKeys&Keys.Control)!=0;
 if(selected!=null&&!ctrl&&handle==0){if(selected.Kind=="Loupe"&&Dist(p,selected.X+selected.Size/2,selected.Y)<12/scale)handle=3;else if(selected.Kind=="Loupe"&&Dist(p,selected.X,selected.Y)<12/scale)handle=4;else if(selected.Kind=="Loupe"&&!selected.InPlace&&Dist(p,selected.SX,selected.SY)<12/scale)handle=2;else if((selected.Kind=="Flèche"||selected.Kind=="Masquer"||selected.Kind=="Surligneur"||selected.Kind=="Zone nette"||selected.Kind=="Flou local")&&Dist(p,selected.BX,selected.BY)<12/scale)handle=1;else if(Dist(p,selected.X,selected.Y)<12/scale)handle=4;}
 if(handle==0){Mark hit=null;for(int i=marks.Count-1;i>=0;i--)if(HitMark(marks[i],p)){hit=marks[i];break;}if(ctrl){if(hit!=null){if(!selection.Add(hit))selection.Remove(hit);selected=selection.Contains(hit)?hit:null;}RefreshSelection();canvas.Invalidate();return;}if(hit==null||!selection.Contains(hit))selection.Clear();selected=hit;if(hit!=null)selection.Add(hit);}
 if(selected!=null){Checkpoint();dragging=true;}
 }else{string text="";Checkpoint();selected=new Mark(){Kind=mode,X=p.X,Y=p.Y,BX=p.X+1,BY=p.Y+1,SX=p.X,SY=p.Y,Size=(float)size.Value,Zoom=(float)zoom.Value,Color=ink.ToArgb(),Width=(float)thickness.Value,Text=text,Link=false};if(mode=="Loupe"){selected.Size=Math.Min(selected.Size,Math.Min(ViewRect.Width,ViewRect.Height)*.65f);selected.InPlace=true;selected.Color=Color.FromArgb(50,50,50).ToArgb();selected.Width=3;selected.Link=false;}marks.Add(selected);selection.Clear();selection.Add(selected);Renumber();dragging=mode=="Flèche"||mode=="Masquer"||mode=="Surligneur"||mode=="Zone nette"||mode=="Flou local";handle=1;tool.SelectedIndex=0;}
 RefreshSelection();canvas.Invalidate();status.Text="Glissez pour déplacer • Ctrl+clic : sélection multiple • Alt : déplacement sans aimantation • ••• : aligner";if(mode=="Texte")BeginInlineText(selected,true);
 }
 void DragMark(object s,MouseEventArgs e){if(panning)return;var p=ImagePoint(e.Location);if(cropDragging){CropMove(p);return;}if(!dragging||selected==null)return;float dx=p.X-last.X,dy=p.Y-last.Y;
 if(handle==1){if(selected.Kind=="Flèche"&&(ModifierKeys&Keys.Shift)!=0){float arrowDx=p.X-selected.X,arrowDy=p.Y-selected.Y;double angle=Math.Round(Math.Atan2(arrowDy,arrowDx)/(Math.PI/4))*(Math.PI/4);float length=(float)Math.Sqrt(arrowDx*arrowDx+arrowDy*arrowDy);p=new PointF(selected.X+length*(float)Math.Cos(angle),selected.Y+length*(float)Math.Sin(angle));}selected.BX=p.X;selected.BY=p.Y;}else if(handle==2){selected.SX=Math.Max(0,Math.Min(photo.Width,p.X));selected.SY=Math.Max(0,Math.Min(photo.Height,p.Y));}else if(handle==3)selected.Size=Math.Max(24,Math.Min(600,Dist(p,selected.X,selected.Y)*2));else if(handle==4&&selected.Kind=="Flèche"){selected.X=p.X;selected.Y=p.Y;}else{var group=new HashSet<Mark>(selection);group.Add(selected);foreach(var m in group)TranslateMark(m,dx,dy);if(group.Count==1)Snap(selected);}last=p;if(handle==3)RefreshSelection();canvas.Invalidate();}
 string Prompt(string title,string initial=""){using(var f=new Form(){Icon=Icon,Text=title,Width=430,Height=150,StartPosition=FormStartPosition.CenterParent}){var input=new TextBox(){Left=16,Top=16,Width=380,Text=initial};var ok=new Button(){Text="Valider",Left=300,Top=55,DialogResult=DialogResult.OK};f.Controls.Add(input);f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK?input.Text:null;}}
