class BufferedPanel:Panel{public BufferedPanel(){DoubleBuffered=true;SetStyle(ControlStyles.Selectable,true);TabStop=true;}}
class RegionPicker:Form {
 Bitmap image;Point start,current;bool drag;public Rectangle Selection;string instructions;
 public RegionPicker(Bitmap b,Rectangle bounds):this(b,bounds,"Glissez pour sélectionner une zone • Entrée : tous les écrans • Échap : annuler"){}
 public RegionPicker(Bitmap b,Rectangle bounds,string hint){instructions=hint;image=b;FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.Manual;Bounds=bounds;TopMost=true;DoubleBuffered=true;Cursor=Cursors.Cross;KeyPreview=true;KeyDown+=delegate(object s,KeyEventArgs e){if(e.KeyCode==Keys.Escape){DialogResult=DialogResult.Cancel;Close();}if(e.KeyCode==Keys.Enter){Selection=new Rectangle(Point.Empty,image.Size);DialogResult=DialogResult.OK;Close();}};MouseDown+=delegate(object s,MouseEventArgs e){start=current=e.Location;drag=true;};MouseMove+=delegate(object s,MouseEventArgs e){if(drag){current=e.Location;Invalidate();}};MouseUp+=delegate{Selection=Rectangle.FromLTRB(Math.Max(0,Math.Min(start.X,current.X)),Math.Max(0,Math.Min(start.Y,current.Y)),Math.Min(image.Width,Math.Max(start.X,current.X)),Math.Min(image.Height,Math.Max(start.Y,current.Y)));if(Selection.Width>2&&Selection.Height>2){DialogResult=DialogResult.OK;Close();}};}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.DrawImageUnscaled(image,0,0);using(var shade=new SolidBrush(Color.FromArgb(100,0,0,0)))e.Graphics.FillRectangle(shade,ClientRectangle);if(drag){var r=Rectangle.FromLTRB(Math.Min(start.X,current.X),Math.Min(start.Y,current.Y),Math.Max(start.X,current.X),Math.Max(start.Y,current.Y));if(r.Width>0&&r.Height>0)e.Graphics.DrawImage(image,r,r,GraphicsUnit.Pixel);e.Graphics.DrawRectangle(Pens.White,r);}using(var font=new Font("Segoe UI",15))e.Graphics.DrawString(instructions,font,Brushes.White,25,25);}
}
